package com.fintaxpro;
import java.util.*;import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;
@RestController public class WorkspaceController{
 final WorkspaceRepository spaces;final UserRepository users;final ObjectMapper json;
 WorkspaceController(WorkspaceRepository s,UserRepository u,ObjectMapper j){spaces=s;users=u;json=j;}
 record Command(String type,Map<String,Object> data,long version){}
 @GetMapping("/api/workspace") public Map<String,Object> get(@AuthenticationPrincipal Jwt jwt)throws Exception{AppUser u=users.findById(jwt.getSubject()).orElseThrow();WorkspaceRecord row=spaces.findById(u.id).orElseThrow();Map<String,Object> out=new LinkedHashMap<>();out.put("state",json.readValue(row.payload,Finance.State.class));out.put("version",row.version);out.put("user",Map.of("name",u.name,"email",u.email));return out;}
 @PostMapping("/api/workspace") @Transactional public Map<String,Object> mutate(@AuthenticationPrincipal Jwt jwt,@RequestBody Command c)throws Exception{WorkspaceRecord row=spaces.locked(jwt.getSubject()).orElseThrow();if(row.version!=c.version)throw new ResponseStatusException(HttpStatus.CONFLICT,"Workspace changed. Refresh and try again.");Finance.State old=json.readValue(row.payload,Finance.State.class);if(old!=null&&c.type.equals("initialize"))throw new IllegalArgumentException("Workspace already initialized.");Finance.State state=Finance.apply(old==null?Finance.empty("My workspace"):old,c.type,c.data==null?Map.of():c.data);String payload=json.writeValueAsString(state);if(payload.length()>3500000)throw new IllegalArgumentException("Workspace storage limit reached.");row.payload=payload;spaces.saveAndFlush(row);return Map.of("state",state,"version",row.version);}
 @GetMapping("/api/users/me") public Map<String,String> me(@AuthenticationPrincipal Jwt jwt){AppUser u=users.findById(jwt.getSubject()).orElseThrow();return Map.of("id",u.id,"name",u.name,"email",u.email);}
}
